const fs=require("fs");
const txt=fs.readFileSync("doom.dis","utf8");
const lines=txt.split("\n");
const re=/^\s+([0-9a-f]{4,8}):\s+([0-9a-f]{8})\s+(\S+)\s*(.*)$/;
const GPR={zero:0,at:1,v0:2,v1:3,a0:4,a1:5,a2:6,a3:7,t0:8,t1:9,t2:10,t3:11,t4:12,t5:13,t6:14,t7:15,s0:16,s1:17,s2:18,s3:19,s4:20,s5:21,s6:22,s7:23,t8:24,t9:25,k0:26,k1:27,gp:28,sp:29,fp:30,ra:31,s8:30};
const gprName=r=>["zero","at","v0","v1","a0","a1","a2","a3","t0","t1","t2","t3","t4","t5","t6","t7","s0","s1","s2","s3","s4","s5","s6","s7","t8","t9","k0","k1","gp","sp","fp","ra"][r];
const fn={}; // major -> subkey -> {mn, n, bad}
let total=0, bad=0;
const immInt=s=>{s=s.trim(); if(s.startsWith("0x")||s.startsWith("-0x"))return parseInt(s,16); return parseInt(s,10);};
for(const ln of lines){
  const m=ln.match(re); if(!m)continue;
  const w=parseInt(m[2],16), mn=m[3], argstr=m[4];
  const maj=w>>>26; total++;
  const sub=(maj===0||maj===0x1F||maj===0x1C)?(w&0x3F):maj;
  const key=maj+":"+sub;
  if(!fn[key])fn[key]={mn:new Set(),n:0,bad:0};
  fn[key].mn.add(mn); fn[key].n++;
  // field extraction
  const rs=(w>>>21)&31, rt=(w>>>16)&31, rd=(w>>>11)&31, fun=w&0x3F;
  // verify per mnemonic
  let ok=true;
