      else if(mn==="addu"||mn==="subu"||mn==="and"||mn==="or"||mn==="xor"||mn==="nor"||mn==="slt"||mn==="sltu"){ if(A[0]!==gprName(rd)||A[1]!==gprName(rs)||A[2]!==gprName(rt))ok=false; }
      else if(mn==="mult"||mn==="multu"||mn==="div"||mn==="divu"){ if(A[0]!==gprName(rs)||A[1]!==gprName(rt))ok=false; }
      else if(mn==="mfhi"||mn==="mflo"||mn==="mthi"||mn==="mtlo"){ if(A[0]!==gprName(rd))ok=false; }
      else if(mn==="move"){ if(!(A[0]===gprName(rd)&&A[1]===gprName(rt)))ok=false; }
      else if(mn==="movz"||mn==="movn"){ if(A[0]!==gprName(rd)||A[1]!==gprName(rs)||A[2]!==gprName(rt))ok=false; }
      else if(mn==="teq"){ if(A[0]!==gprName(rs)||A[1]!==gprName(rt))ok=false; }
      break; }
    case 0x1C: { // 3-op mul family
      if(mn==="mul"||mn==="mulu"){ if(A[0]!==gprName(rd)||A[1]!==gprName(rs)||A[2]!==gprName(rt))ok=false; }
      else ok=false;
      break; }
    case 0x1F: { // SPECIAL2
      if(mn==="seb"||mn==="seh"){ if(A[0]!==gprName(rd)||A[1]!==gprName(rs))ok=false; }
      else if(mn==="wsbh"){ if(A[0]!==gprName(rd)||A[1]!==gprName(rs))ok=false; }
      else if(mn==="ext"){ if(A[0]!==gprName(rd)||A[1]!==gprName(rs)||immInt(A[2])!==((w>>>6)&31)||immInt(A[3])!==fun)ok=false; }
      else if(mn==="ins"){ if(A[0]!==gprName(rd)||A[1]!==gprName(rs)||A[2]!==gprName(rt))ok=false; }
      break; }
    case 1: { // REGIMM
      if(mn==="bltz"||mn==="bgezt"||mn==="bgez"||mn==="bgtz"){ if(A[0]!==gprName(rs))ok=false; }
      break; }
    case 4: case 5: {
      if(mn==="beq"||mn==="bne"||mn==="beqz"||mn==="bnez"){ if(A[0]!==gprName(rs)||A[1]!==gprName(rt))ok=false; }
      break; }
    case 9: case 0xA: case 0xB: case 0xC: case 0xD: case 0xE: case 8: {
      if(mn==="addiu"||mn==="slti"||mn==="sltiu"||mn==="andi"||mn==="ori"||mn==="xori"||mn==="addi"||mn==="li"){ if(A[0]!==gprName(rt)||A[1]!==gprName(rs))ok=false; }
      break; }
    case 0x20: case 0x21: case 0x22: case 0x23: case 0x24: case 0x25: case 0x26:
    case 0x28: case 0x29: case 0x2A: case 0x2B: case 0x2E: case 0x31: case 0x35: case 0x3D: {
      // S-type: rt, base, offset  (for cop1: ft, base)
      if(mn==="lwc1"||mn==="ldc1"||mn==="swc1"||mn==="sdc1"){
        const ft=parseInt(A[0].replace("$f","")); if(ft!==rt)ok=false;
      } else if(mn!=="nop"){
        if(A[0]!==gprName(rt))ok=false;
      }
      break; }
    case 0x11: { // COP1 or BC1
      if(mn==="bc1t"){ /* handled separately */ }
      else ok=false; // verify below in cop1 section
      break; }
    case 0x16: { // maybe BC1F?
      ok=false; break; }
  }
  }catch(e){ok=false;}
  if(!ok){fn[key].bad++; if(fn[key].bad<=2)fn[key].lastbad=ln.trim();}
}
const out={};
const keys=Object.keys(fn).sort((a,b)=>{const [ma,sa]=a.split(":").map(Number),[mb,sb]=b.split(":").map(Number);return ma-mb||sa-sb;});
for(const k of keys){
  const e=fn[k];
  out[k]={mn:[...e.mn],n:e.n,bad:e.bad,...(e.lastbad?{ex:e.lastbad}:{})};
}
console.log(JSON.stringify(out,null,1));
console.log("total",total);
